import argparse
import csv
import json

def parse_amount(s):
    s = s.strip()
    if not s:
        return None
    s = s.replace('$', '').replace(',', '')
    if s.startswith('-'):
        return -float(s[1:])
    return float(s)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)

    path = payload["path"]

    total = 0.0
    with open(path, 'r', newline='') as f:
        reader = csv.reader(f)
        rows = list(reader)

    if not rows:
        print("0.00")
        return

    header = rows[0]
    amount_col = None
    for i, col in enumerate(header):
        if col.strip().lower() == 'amount':
            amount_col = i
            break

    if amount_col is None:
        print("0.00")
        return

    for row in rows[1:]:
        if not row or all(not cell.strip() for cell in row):
            continue
        if amount_col >= len(row):
            continue
        try:
            val = parse_amount(row[amount_col])
            if val is not None:
                total += val
        except ValueError:
            continue

    print(f"{total:.2f}")

if __name__ == "__main__":
    main()

import argparse
import csv
import json
from datetime import date


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    dates = []
    with open(path, "r", newline="") as f:
        reader = csv.reader(f)
        header = next(reader, None)
        date_col = 0
        if header:
            for i, col in enumerate(header):
                if col.lower().strip() == "date":
                    date_col = i
                    break
        for row in reader:
            if not row:
                continue
            if date_col >= len(row):
                continue
            value = row[date_col].strip()
            if not value:
                continue
            try:
                d = date.fromisoformat(value)
            except ValueError:
                continue
            dates.append(d)

    if len(dates) < 2:
        print(0)
        return

    diff = max(dates) - min(dates)
    print(diff.days)


if __name__ == "__main__":
    main()

import argparse
import json


def parse_time(s):
    parts = s.split(":")
    return int(parts[0]) * 3600 + int(parts[1]) * 60 + int(parts[2])


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload.get("path", "/inputs/server.log")

    count = 0
    start = 8 * 3600
    end = 8 * 3600 + 30 * 60

    with open(path, "r") as f:
        for line in f:
            line = line.rstrip("\n").rstrip("\r")
            if not line:
                continue
            parts = line.split(" ", 2)
            if len(parts) < 3:
                continue
            time_str, level, _ = parts
            if level != "ERROR":
                continue
            try:
                t = parse_time(time_str)
            except (ValueError, IndexError):
                continue
            if start <= t < end:
                count += 1

    print(count)


if __name__ == "__main__":
    main()

import argparse
import csv
import json
from datetime import date

def parse_date(s):
    s = s.strip()
    parts = s.split("-")
    if len(parts) != 3:
        return None
    try:
        y, m, d = int(parts[0]), int(parts[1]), int(parts[2])
        return date(y, m, d)
    except ValueError:
        return None

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    params = json.loads(args.payload)
    path = params["path"]

    dates = []
    with open(path, "r", newline="") as f:
        reader = csv.reader(f)
        for row in reader:
            for cell in row:
                d = parse_date(cell)
                if d is not None:
                    dates.append(d)

    if len(dates) < 2:
        print(0)
        return

    diff = (max(dates) - min(dates)).days
    print(diff)

if __name__ == "__main__":
    main()

import argparse
import csv
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    params = json.loads(args.payload)

    customers_path = params["customers_path"]
    orders_path = params["orders_path"]

    west_customers = set()
    with open(customers_path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            region = (row.get("region") or "").strip().lower()
            if region == "west":
                west_customers.add(row.get("customer_id"))

    total = 0.0
    with open(orders_path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            cid = row.get("customer_id")
            if cid in west_customers:
                raw = (row.get("amount") or "0").strip()
                try:
                    total += float(raw)
                except ValueError:
                    pass

    if total == int(total):
        print(int(total))
    else:
        print(total)


if __name__ == "__main__":
    main()

import argparse
import csv
import json


def parse_amount(s):
    s = s.strip()
    if not s:
        return None
    cleaned = s.replace('$', '').replace(',', '').replace(' ', '')
    if cleaned.startswith('(') and cleaned.endswith(')'):
        cleaned = '-' + cleaned[1:-1]
    if not cleaned:
        return None
    try:
        return float(cleaned)
    except ValueError:
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)

    path = payload["path"]

    with open(path, 'r', newline='') as f:
        content = f.read()

    lines = [line for line in content.splitlines() if line.strip()]

    if not lines:
        print("0.00")
        return

    reader = csv.reader(lines)
    rows = list(reader)

    if not rows:
        print("0.00")
        return

    header = rows[0]
    amount_col = None
    for i, col in enumerate(header):
        if col.strip().lower() == 'amount':
            amount_col = i
            break

    if amount_col is not None:
        data_rows = rows[1:]
    else:
        amount_col = len(header) - 1
        data_rows = rows

    total = 0.0
    for row in data_rows:
        if amount_col >= len(row):
            continue
        val = parse_amount(row[amount_col])
        if val is not None:
            total += val

    print(f"{total:.2f}")


if __name__ == "__main__":
    main()
